-- =============================================================================
-- 0047 — Mortandad Ganaderas: formulario condicionado + actualización Excel
-- Fuente: GVA_F(10).xlsx, hoja Mortandad, 278 filas válidas al 12/10/2026.
--
-- Agrega:
--   - vaca_parida (Sí/No)
--   - numero_corral y numero_tropa
--   - catálogos dependientes por campo/actividad para la app
--   - upsert idempotente del histórico completo recibido
--
-- Se omite una fila vacía del Excel (ID 7e6bdc1f) que no tiene campo ni fecha.
-- =============================================================================

BEGIN;

ALTER TABLE mortandad
  ADD COLUMN IF NOT EXISTS numero_corral TEXT,
  ADD COLUMN IF NOT EXISTS numero_tropa TEXT,
  ADD COLUMN IF NOT EXISTS vaca_parida BOOLEAN;

COMMENT ON COLUMN mortandad.numero_corral IS
  'Identificador del corral cuando el evento pertenece al campo Corrales.';
COMMENT ON COLUMN mortandad.numero_tropa IS
  'Número o denominación de tropa informado para mortandad en Corrales.';
COMMENT ON COLUMN mortandad.vaca_parida IS
  'Indica si la vaca muerta ya había parido; NULL significa no informado/no aplica.';

-- Configuración dinámica consumida por la app. Los valores guardados conservan
-- las abreviaturas históricas para no romper métricas; `etiquetas` define cómo
-- se muestran al operario.
UPDATE clientes
SET catalogos = jsonb_set(
      COALESCE(catalogos, '{}'::jsonb),
      '{mortandad}',
      '{
        "categorias": ["Novillito","Novillo","TernH","TernM","Toro Venta","Toros","Vac Descarte","Vac Repos","Vaq 1","Vaq 1° Servicio","Vaq 2","Vaq 2° Servicio","Vc Preñ","Vc Venta"],
        "actividades": ["Cria","Recria P","engorde","Invernada","Destete Precoz"],
        "causaTipos": ["Muerte Señalado","Nacido Muerto","Desconocido"],
        "actividadesPorCampo": {
          "Corrales": ["engorde","Invernada","Destete Precoz"],
          "__otros__": ["Cria","Recria P"]
        },
        "categoriasPorActividad": {
          "Cria": ["Vc Preñ","Vc Venta","Toros","Toro Venta","TernH","TernM","Vaq 1° Servicio","Vaq 2° Servicio"],
          "Recria P": ["Vaq 2","Novillo","Vaq 1","Novillito"],
          "engorde": ["Vc Venta","Novillo","Vaq 2"],
          "Invernada": ["Vaq 1","Novillito"],
          "Destete Precoz": ["TernH","TernM"]
        },
        "etiquetas": {
          "Cria": "Cría",
          "Recria P": "Recría a pasto",
          "engorde": "Engorde",
          "Vc Preñ": "Vacas preñadas",
          "Vc Venta": "Vaca venta",
          "TernH": "Ternero H",
          "TernM": "Ternero M",
          "Vaq 1° Servicio": "Vaquilla 15M",
          "Vaq 2° Servicio": "Vaquilla 27M",
          "Vaq 1": "Vaquilla 1",
          "Vaq 2": "Vaquilla 2"
        }
      }'::jsonb,
      true
    ),
    updated_at = NOW()
WHERE id = 'ganaderas';

