  ('0a390fb6', 'Corrales', NULL, '1223alevera@gmail.com', DATE '2026-10-12', 'TernH', 'Destete Precoz', 'Desconocido', '004678-9839', 'No se podía parar. Inmóvil completamente el cuerpo', 'Enf1', 'Trh1.9', NULL)
), resolved AS (
  SELECT
    src.*,
    c.id AS campo_id,
    (
      SELECT l.id
      FROM lotes l
      WHERE l.cliente_id = 'ganaderas'
        AND l.campo_id = c.id
        AND lower(trim(l.nombre)) = lower(trim(src.lote))
      ORDER BY l.id
      LIMIT 1
    ) AS lote_id
  FROM src
  JOIN campos c
    ON c.cliente_id = 'ganaderas'
   AND lower(trim(c.nombre)) = lower(trim(src.campo))
)
INSERT INTO mortandad (
  id, cliente_id, campo_id, lote_id, usuario_email, fecha,
  categoria, actividad, causa_detalle, caravana_numero, observaciones,
  numero_corral, numero_tropa, vaca_parida
)
SELECT
  id, 'ganaderas', campo_id, lote_id, usuario_email, fecha,
  categoria, actividad, causa_detalle, caravana_numero, observaciones,
  numero_corral, numero_tropa, vaca_parida
FROM resolved
ON CONFLICT (id) DO UPDATE SET
  cliente_id      = EXCLUDED.cliente_id,
  campo_id        = EXCLUDED.campo_id,
  lote_id         = EXCLUDED.lote_id,
  usuario_email   = EXCLUDED.usuario_email,
  fecha           = EXCLUDED.fecha,
  categoria       = EXCLUDED.categoria,
  actividad       = EXCLUDED.actividad,
  causa_detalle   = EXCLUDED.causa_detalle,
  caravana_numero = EXCLUDED.caravana_numero,
  observaciones   = EXCLUDED.observaciones,
  numero_corral   = EXCLUDED.numero_corral,
  numero_tropa    = EXCLUDED.numero_tropa,
  vaca_parida     = EXCLUDED.vaca_parida;

COMMIT;

